37	import { SimpleSleepScheduler } from "../adapters/scheduler/simple-sleep.js";
38	import { RealClock } from "../adapters/clock/real.js";
39	
40	export interface LocalDockerProfileOpts {
41	  /** Options forwarded to DockerRunAdapter. */
42	  executor?: DockerRunAdapterOpts;
43	  /** Options forwarded to HttpBrokerAdapter. */
44	  broker?: HttpBrokerAdapterOpts;
45	  /** Base URL of the Go broker service. Defaults to http://broker:7000. */
46	  brokerUrl?: string;
47	  /** Git identity for WorkflowStatePort operations. */
48	  gitAuthorEmail: string;
49	  gitAuthorName?: string;
50	  sshKeyPath?: string;
51	}
52	
53	/** The broker is part of the profile bundle so callers can call getCallbackUrl(). */
54	export interface LocalDockerProfileBundle extends RuntimePorts {
55	  broker: HttpBrokerAdapter;
56	  executor: DockerRunAdapter;
57	}
58	
59	/**
60	 * Create a RuntimePorts bundle wired for the local-docker profile.
61	 *
62	 * The broker's getCallbackUrl() returns the Go broker service callback
63	 * URL (e.g. http://broker:7000/callback). Pass this to ExecutorPortInput
64	 * as callbackUrl when submitting tasks.
65	 *
66	 * Example:
67	 *   const bundle = createLocalDockerProfile({ gitAuthorEmail: '...', brokerUrl: 'http://broker:7000' });
68	 *   const callbackUrl = bundle.broker.getCallbackUrl();
69	 *   // pass bundle to orchestrator concerns...
70	 *   bundle.executor.stopOrphanSweep(); // on graceful shutdown
71	 */
72	export function createLocalDockerProfile(
73	  opts: LocalDockerProfileOpts,
74	): LocalDockerProfileBundle {
75	  const brokerUrl = opts.brokerUrl ?? opts.broker?.brokerUrl ?? "http://broker:7000";
76	  const broker = new HttpBrokerAdapter(
77	    opts.broker ?? { brokerUrl },
78	  );
79	  const executor = new DockerRunAdapter({ ...opts.executor, broker });
80	  return {
81	    executor,
82	    broker,
83	    briefing: new LocalFileBriefingAdapter(),
84	    workflowState: new GitWorkflowStateAdapter({
85	      gitAuthorEmail: opts.gitAuthorEmail,
86	      gitAuthorName: opts.gitAuthorName,
87	      sshKeyPath: opts.sshKeyPath,
88	    }),
89	    credential: new EnvCredentialAdapter(),
90	    workspacePull: new GitClonePullAdapter(),
91	    emitter: new StdoutJsonEmitter(),
92	    scheduler: new SimpleSleepScheduler(),
93	    clock: new RealClock(),
94	  };
95	}
