      const rebaseHandle = randomUUID();
      const rebaseNonce = randomUUID();
      const rebaseResultPath = join(tmpdir(), `rebase-result-${pr.taskId}-${rebaseHandle.slice(0, 8)}.json`);
      let rebaseTask: Task;
      try {
        rebaseTask = parseYaml(
          readFileSync(taskYamlAbsPath(wsRoot, pr.featureId, pr.taskId), "utf-8"),
