      const rebaseBriefingContent = [
        `# Rebase: ${pr.taskId}`,
        ``,
        `Branch \`${rebaseTaskBranch}\` has a PR conflict (mergeable: false).`,
        `Rebase it onto \`${featureBranchName(pr.featureId)}\` and resolve any conflicts.`,
      ].join("\n");
      const rebaseBriefingPath = await ports.briefing.put(
        `rebase-${pr.taskId}-${rebaseHandle.slice(0, 8)}`,
        rebaseBriefingContent,
